  '{"identity": {"id": "SCH000278", "code": "SCH000278", "slug": "pradhan-mantri-viksit-bharat-rozgar-yojana-pm-vbry-employment-linked-incentive-scheme", "name": "Pradhan Mantri Viksit Bharat Rozgar Yojana (PM-VBRY) – Employment Linked Incentive Scheme", "fullName": "Pradhan Mantri Viksit Bharat Rozgar Yojana (PM-VBRY) – Employment Linked Incentive Scheme", "shortName": "PM-VBRY", "status": "active", "legacyCodes": [{"system": "mss_v3_1", "code": "NEW2026-050"}]}, "classification": {"government": {"level": "central", "ministryId": null, "ministryText": "Ministry of Labour and Employment", "departmentText": "Employees'' Provident Fund Organisation (EPFO)", "implementingAgencyIds": []}, "schemeType": "financial_support", "category": "financial_support", "tags": ["company", "financial_support", "individual", "manufacturing", "medium_enterprise", "micro_enterprise", "services", "small_enterprise"]}, "content": {"overview": {"summary": "Employment Linked Incentive scheme announced on 15 August 2025 to support job creation, employability and social security.", "description": "Employment Linked Incentive scheme announced on 15 August 2025 to support job creation, employability and social security. Applies to jobs created between 1 August 2025 and 31 July 2027; outlay of ₹99,446 crore. Part A supports first-time employees registered with EPFO; Part B supports employers who create additional jobs.", "objectives": ["Applies to jobs created between 1 August 2025 and 31 July 2027; outlay of ₹99,446 crore.", "Part A supports first-time employees registered with EPFO; Part B supports employers who create additional jobs."], "keyPointers": []}, "eligibility": {"narrative": {"criteria": ["Part A: first-time employees registered with EPFO earning up to ₹1 lakh per month.", "UAN must be generated/authenticated through Face Authentication Technology (FAT) on the UMANG App.", "Part B: EPFO-registered employers hiring additional employees with salary up to ₹1 lakh per month."], "exclusi