derIds": [], "providerText": null, "conditions": [], "description": null}, "technologySupport": {"applicable": null, "modalities": [], "durationText": null, "providerIds": [], "providerText": null, "conditions": [], "description": null}, "currency": "INR", "disbursement": {"mode": null, "modeText": null, "instalments": null, "text": null}}, "requiredDocuments": [], "applicationProcess": {"mode": "offline", "modeText": "Application via offline channel", "onlineUrl": null, "steps": [{"step": 1, "title": "Step 1", "description": "Register with NAFED/NCCF and sign the procurement agreement to get assured purchase.", "mode": "both", "url": null, "documents": []}, {"step": 2, "title": "Step 2", "description": "For seed kits and processing units, contact the State agriculture department.", "mode": "offline", "url": null, "documents": []}], "services": []}, "contacts": {"national": [{"url": "https://www.pib.gov.in/PressReleasePage.aspx?PRID=2173547&reg=3&lang=2", "title": "Official source"}], "helplines": []}, "sources": [{"id": "SCH000284-SRC001", "name": "Union Cabinet Approves Mission for Aatmanirbharta in Pulses for 2025-26 to 2030-31 – PIB", "url": "https://www.pib.gov.in/PressReleasePage.aspx?PRID=2173547&reg=3&lang=2", "publisherText": "Ministry of MSME Schemes Booklet 2025-26", "type": "official_booklet", "isPrimary": true}], "schemeUrl": "https://www.pib.gov.in/PressReleasePage.aspx?PRID=2173547&reg=3&lang=2"}, "relationships": {"references": []}, "localization": {"en": {"name": "Mission for Aatmanirbharta in Pulses", "shortName": null, "summary": "Six-year mission (2025-26 to 2030-31) with ₹11,440 crore outlay to make India self-reliant in pulses.", "description": "Six-year mission (2025-26 to 2030-31) with ₹11,440 crore outlay to make India self-reliant in pulses. Targets by 2030-31: 350 lakh tonnes production, 310 lakh hectares area, yield 1130 kg/ha; ~2 crore farmers to benefit.", "objective": "Targets by 2030-31: 350 lakh tonnes production, 310 lakh hectares area, yield 1130 kg/ha; ~2 crore farmers to benefit.", "eligibilityText": "Pulse farmers in participating states (registration and agreement with NAFED/NCCF needed for assured procurement). Entrepreneurs/units setting up pulses processing facilities (for processing subsidy).", "benefitsText": "100% procurement of tur, urad and masoor by NAFED and NCCF in participating states for four years from registered farmers who enter agreements. 88 lakh seed kits distributed free of cost to farmers. 1000 pulses processing units with subsidy up to ₹25 lakh per unit.", "applicationText": "Register with NAFED/NCCF and sign the procurement agreement to get assured purchase. For seed kits and processing units, contact the State agriculture department."}, "ta": {"name": null, "shortName": null, "summary": null, "description": null, "objective": null, "eligibilityText": null, "benefitsText": null, "applicationText": null}, "hi": {"name": "दलहन में आत्मनिर्भरता मिशन", "shortName": null, "summary": "दलहन में आत्मनिर्भरता हेतु ₹11,440 करोड़ परिव्यय वाला छह वर्षीय मिशन (2025-26 से 2030-31)।", "description": "दलहन में आत्मनिर्भरता हेतु ₹11,440 करोड़ परिव्यय वाला छह वर्षीय मिशन (2025-26 से 2030-31)। 2030-31 तक लक्ष्य: 350 लाख टन उत्पादन, 310 लाख हेक्टेयर क्षेत्र, 1130 किग्रा/हेक्टेयर उपज; लगभग 2 करोड़ किसान लाभान्वित।", "objective": "दलहन में आत्मनिर्भरता हेतु ₹11,440 करोड़ परिव्यय वाला छह वर्षीय मिशन (2025-26 से 2030-31)।", "eligibilityText": "भाग लेने वाले राज्यों के दलहन किसान (सुनिश्चित खरीद हेतु नेफेड/एनसीसीएफ के साथ पंजीकरण और अनुबंध आवश्यक)। दाल प्रसंस्करण इकाइयां स्थापित करने वाले उद्यमी (प्रसंस्करण सब्सिडी हेतु)।", "benefitsText": "भाग लेने वाले राज्यों में चार वर्षों तक पंजीकृत एवं अनुबंधित किसानों से तुअर, उड़द और मसूर की 100% खरीद नेफेड और एनसीसीएफ द्वारा। किसानों को 88 लाख बीज किट निःशुल्क वितरित। 1000 दाल प्रसंस्करण इकाइयां, प्रति इकाई अधिकतम ₹25 लाख सब्सिडी।", "applicationText": "सुनिश्चित खरीद हेतु नेफेड/एनसीसीएफ में पंजीकरण कर खरीद अनुबंध करें। बीज किट और प्रसंस्करण इकाई हेतु राज्य कृषि विभाग से संपर्क करें।"}}, "search": {"aliases": {"en": ["Mission for Aatmanirbharta in Pulses"], "ta": [], "hi": ["दलहन में आत्मनिर्भरता मिशन"]}, "keywords": {"en": ["mission", "aatmanirbharta", "pulses"], "ta": [], "hi": []}, "synonyms": []}, "verification": {"status": "verified", "confidence": "high", "verifiedAt": "2026-10-04", "verifiedAgainst": ["SCH000284-SRC001"], "verifiedFields": [{"field": "content.schemeUrl", "value": "https://www.pib.gov.in/PressReleasePage.aspx?PRID=2173547&reg=3&lang=2", "sourceTier": 5, "url": "https://www.pib.gov.in/PressReleasePage.aspx?PRID=2173547&reg=3&lang=2", "retrievedAt": "2026-10-04", "outcome": "confirmed", "note": "Official scheme portal"}], "disputedFields": [], "missingFields": [], "notes": "Approved Oct 2025 for 2025-26 to 2030-31; launched 11 Oct 2025.; NAFED eSamridhi / NCCF registration portal URLs not verified; left null.; Processing subsidy percentage/eligibility details not in source.; [agent_flag] NAFED eSamridhi / NCCF registration portal URLs not verified; left null.; [agent_flag] Processing subsidy percentage/eligibility details not in source."}, "provenance": {"pipelineVersion": "catalog-v3-1-migration", "transformationNotes": ["Migrated from mss_scheme_data_v3_1 (ID: NEW2026-056)", "Action: ADD_NEW"], "translations": {"ta": {"status": "none", "reviewRequired": true, "engine": "none", "note": "Tamil translation pending"}, "hi": {"status": "machine", "reviewRequired": true, "source": "booklet_2025_26_machine_hi", "generatedAt": "2026-10-04T00:00:00Z"}}}, "metadata": {"catalogVersion": "1.35.0-alpha", "revision": 1, "schemaVersion": "1.0.0", "createdAt": "2026-10-04T13:50:15Z", "updatedAt": "2026-10-04T13:50:15Z"}}'::jsonb,
