ds": [], "providerText": null, "conditions": [], "description": null}, "technologySupport": {"applicable": null, "modalities": [], "durationText": null, "providerIds": [], "providerText": null, "conditions": [], "description": null}, "currency": "INR", "disbursement": {"mode": null, "modeText": null, "instalments": null, "text": null}}, "requiredDocuments": [{"documentTypeId": "CMN000001", "name": "Electricity bill / consumer number", "mandatory": true}, {"documentTypeId": "CMN000001", "name": "Cancelled cheque", "mandatory": true}, {"documentTypeId": "CMN000001", "name": "Bank details", "mandatory": true}], "applicationProcess": {"mode": "online", "modeText": "Application via online channel", "onlineUrl": "https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=2010133&reg=48&lang=2", "steps": [{"step": 1, "title": "Step 1", "description": "Register on the national portal with State, DISCOM, consumer number and mobile number.", "mode": "online", "url": "https://pmsuryaghar.gov.in", "documents": ["Electricity bill / consumer number"]}, {"step": 2, "title": "Step 2", "description": "Apply for rooftop solar; after DISCOM feasibility approval, install through a registered vendor.", "mode": "online", "url": null, "documents": []}, {"step": 3, "title": "Step 3", "description": "Submit plant details and apply for net meter; after inspection obtain commissioning certificate.", "mode": "online", "url": null, "documents": []}, {"step": 4, "title": "Step 4", "description": "Submit bank details and cancelled cheque on the portal; subsidy credited within 30 days.", "mode": "online", "url": null, "documents": ["Cancelled cheque", "Bank details"]}], "services": []}, "contacts": {"national": [{"url": "https://pmsuryaghar.gov.in", "title": "National Portal"}], "helplines": []}, "sources": [{"id": "SCH000289-SRC001", "name": "Cabinet approves PM-Surya Ghar: Muft Bijli Yojana for installing rooftop solar in One Crore households – PIB", "url": "https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=2010133&reg=48&lang=2", "publisherText": "Ministry of MSME Schemes Booklet 2025-26", "type": "official_booklet", "isPrimary": true}, {"id": "SCH000289-SRC003", "name": "Official Source", "url": "https://static.pib.gov.in/WriteReadData/specificdocs/documents/2025/mar/doc2025313520001.pdf", "publisherText": "Government of India", "type": "official_portal", "isPrimary": false}], "schemeUrl": "https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=2010133&reg=48&lang=2"}, "relationships": {"references": []}, "localization": {"en": {"name": "PM Surya Ghar: Muft Bijli Yojana", "shortName": null, "summary": "Rooftop solar for one crore households with ₹75,021 crore outlay; target by 2026-27.", "description": "Rooftop solar for one crore households with ₹75,021 crore outlay; target by 2026-27. A Model Solar Village in each district (₹1 crore per selected village). Expected to create about 17 lakh direct jobs in manufacturing, logistics, sales, installation and O&M — opportunity for local vendors/MSMEs.", "objective": "A Model Solar Village in each district (₹1 crore per selected village).", "eligibilityText": "Indian household owning a house with a roof suitable for solar panels. Valid electricity connection; not availed any other subsidy for solar panels.", "benefitsText": "Central Financial Assistance: ₹30,000 for 1 kW, ₹60,000 for 2 kW, ₹78,000 for 3 kW or higher. Collateral-free low-interest loans of around 7%. Subsidy credited to bank account within about 30 days after commissioning.", "applicationText": "Register on the national portal with State, DISCOM, consumer number and mobile number. Apply for rooftop solar; after DISCOM feasibility approval, install through a registered vendor. Submit plant details and apply for net meter; after inspection obtain commissioning certificate. Submit bank details and cancelled cheque on the portal; subsidy credited within 30 days."}, "ta": {"name": null, "shortName": null, "summary": null, "description": null, "objective": null, "eligibilityText": null, "benefitsText": null, "applicationText": null}, "hi": {"name": "पीएम सूर्य घर: मुफ्त बिजली योजना", "shortName": null, "summary": "₹75,021 करोड़ परिव्यय से एक करोड़ घरों पर रूफटॉप सोलर; लक्ष्य 2026-27 तक।", "description": "₹75,021 करोड़ परिव्यय से एक करोड़ घरों पर रूफटॉप सोलर; लक्ष्य 2026-27 तक। प्रत्येक जिले में एक मॉडल सौर गांव (प्रति चयनित गांव ₹1 करोड़)। विनिर्माण, लॉजिस्टिक्स, बिक्री, स्थापना और रखरखाव में लगभग 17 लाख प्रत्यक्ष रोजगार — स्थानीय विक्रेताओं/एमएसएमई के लिए अवसर।", "objective": "₹75,021 करोड़ परिव्यय से एक करोड़ घरों पर रूफटॉप सोलर; लक्ष्य 2026-27 तक।", "eligibilityText": "सौर पैनल हेतु उपयुक्त छत वाले घर का स्वामी भारतीय परिवार। वैध बिजली कनेक्शन; सौर पैनल हेतु कोई अन्य सब्सिडी न ली हो।", "benefitsText": "केंद्रीय वित्तीय सहायता: 1 किलोवाट पर ₹30,000, 2 किलोवाट पर ₹60,000, 3 किलोवाट या अधिक पर ₹78,000। लगभग 7% ब्याज पर बिना गारंटी के ऋण। कमीशनिंग के बाद लगभग 30 दिनों में सब्सिडी बैंक खाते में।", "applicationText": "राज्य, डिस्कॉम, उपभोक्ता संख्या और मोबाइल नंबर से राष्ट्रीय पोर्टल पर पंजीकरण करें। रूफटॉप सोलर हेतु आवेदन करें; डिस्कॉम की व्यवहार्यता स्वीकृति के बाद पंजीकृत विक्रेता से स्थापित कराएं। संयंत्र विवरण जमा कर नेट मीटर हेतु आवेदन करें; निरीक्षण के बाद कमीशनिंग प्रमाणपत्र प्राप्त करें। पोर्टल पर बैंक विवरण और रद्द चेक जमा करें; 30 दिनों में सब्सिडी।"}}, "search": {"aliases": {"en": ["PM Surya Ghar: Muft Bijli Yojana"], "ta": [], "hi": ["पीएम सूर्य घर: मुफ्त बिजली योजना"]}, "keywords": {"en": ["surya", "ghar", "muft", "bijli", "yojana"], "ta": [], "hi": []}, "synonyms": []}, "verification": {"status": "verified", "confidence": "high", "verifiedAt": "2026-10-04", "verifiedAgainst": ["SCH000289-SRC001"], "verifiedFields": [{"field": "content.schemeUrl", "value": "https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=2010133&reg=48&lang=2", "sourceTier": 5, "url": "https://www.pib.gov.in/PressReleaseIframePage.aspx?PRID=2010133&reg=48&lang=2", "retrievedAt": "2026-10-04", "outcome": "confirmed", "note": "Official scheme portal"}], "disputedFields": [], "missingFields": [], "notes": "Running; 23.96 lakh households covered as per PIB (late 2025).; Vendor/MSME registration process on the portal not detailed on source; vendor angle noted in description only.; Step 1 field list (State, DISCOM) partially inferred; source says login with consumer number and mobile.; [agent_flag] Vendor/MSME registration process on the portal not detailed on source; vendor angle noted in description only.; [agent_flag] Step 1 field list (State, DISCOM) partially inferred; source says login with consumer number and mobile."}, "provenance": {"pipelineVersion": "catalog-v3-1-migration", "transformationNotes": ["Migrated from mss_scheme_data_v3_1 (ID: NEW2026-061)", "Action: ADD_NEW"], "translations": {"ta": {"status": "none", "reviewRequired": true, "engine": "none", "note": "Tamil translation pending"}, "hi": {"status": "machine", "reviewRequired": true, "source": "booklet_2025_26_machine_hi", "generatedAt": "2026-10-04T00:00:00Z"}}}, "metadata": {"catalogVersion": "1.35.0-alpha", "revision": 1, "schemaVersion": "1.0.0", "createdAt": "2026-10-04T13:50:15Z", "updatedAt": "2026-10-04T13:50:15Z"}}'::jsonb,
